  /**
   * Get a valid access token along with its metadata for an MCP server,
   * refreshing if necessary.
   *
   * Unlike {@link getValidToken}, this returns the token type and, when known,
   * the absolute expiration timestamp so callers can cache the token and
   * compute the remaining lifetime.
   *
   * @param serverName The name of the MCP server
   * @param config OAuth configuration
   * @returns The token metadata or null if no valid credentials are found or
   *   the refresh fails
   */
  async getValidTokenWithMetadata(
    serverName: string,
    config: MCPOAuthConfig,
  ): Promise<{
    accessToken: string;
    tokenType: string;
    expiresAt?: number;
  } | null> {
    debugLogger.debug(
      `Getting valid token with metadata for server: ${serverName}`,
    );
    const credentials = await this.tokenStorage.getCredentials(serverName);

    if (!credentials) {
      debugLogger.debug(`No credentials found for server: ${serverName}`);
      return null;
    }

    const { token } = credentials;

    // Check if token is still valid.
    if (!this.tokenStorage.isTokenExpired(token)) {
      debugLogger.debug(
        `Returning valid token with metadata for server: ${serverName}`,
      );
      return {
        accessToken: token.accessToken,
        tokenType: token.tokenType || 'Bearer',
        expiresAt: token.expiresAt,
      };
    }

    // Try to refresh if we have a refresh token.
    if (token.refreshToken && config.clientId && credentials.tokenUrl) {
      try {
        debugLogger.log(
          `Refreshing expired token for MCP server: ${serverName}`,
        );

        const newTokenResponse = await this.refreshAccessToken(
          config,
          token.refreshToken,
          credentials.tokenUrl,
          credentials.mcpServerUrl,
        );

        // Update stored token.
        const newToken: OAuthToken = {
          accessToken: newTokenResponse.access_token,
          tokenType: newTokenResponse.token_type,
          refreshToken: newTokenResponse.refresh_token || token.refreshToken,
          scope: newTokenResponse.scope || token.scope,
        };

        if (newTokenResponse.expires_in) {
          newToken.expiresAt = Date.now() + newTokenResponse.expires_in * 1000;
        }

        await this.tokenStorage.saveToken(
          serverName,
          newToken,
          config.clientId,
          credentials.tokenUrl,
          credentials.mcpServerUrl,
        );

        return {
          accessToken: newToken.accessToken,
          tokenType: newToken.tokenType || 'Bearer',
          expiresAt: newToken.expiresAt,
        };
      } catch (error) {
        coreEvents.emitFeedback(
          'error',
          'Failed to refresh auth token.',
          error,
        );
        // Remove invalid token
        await this.tokenStorage.deleteCredentials(serverName);
      }
    }

    return null;
  }
