import type { MCPServerConfig } from '../config/config.js';
import { MCPOAuthProvider } from './oauth-provider.js';
import { debugLogger } from '../utils/debugLogger.js';

/**
 * Shape of the tokens returned to the MCP transport's OAuth provider hook.
 *
 * This mirrors the subset of the SDK's `OAuthTokens` type that we can resolve
 * from stored credentials: the access token and, when the expiration time is
 * known, the number of seconds until it expires.
 */
export interface DynamicOAuthTokens {
  access_token: string;
  expires_in?: number;
}

/**
 * A dynamic OAuth token provider for MCP transports.
 *
 * Rather than resolving a single access token when the transport is created,
 * this provider fetches (and refreshes) tokens on demand via
 * {@link MCPOAuthProvider.getValidTokenWithMetadata}. This ensures the
 * transport always uses a valid token, even for long-lived connections where
 * the initial token would otherwise expire.
 *
 * Tokens with a known expiration time are cached in memory to avoid redundant
 * credential lookups. Tokens without an expiration timestamp are re-fetched on
 * every request, since we cannot know when they become invalid.
 */
export class DynamicStoredOAuthProvider {
  private readonly oauthProvider: MCPOAuthProvider;

  /**
   * The most recently resolved token, cached only when its expiration time is
   * known. Used to avoid redundant lookups until the token expires.
   */
  private cachedToken:
    | {
        access_token: string;
        expiresAt: number;
      }
    | undefined;

  constructor(
    private readonly serverName: string,
    private readonly serverConfig: MCPServerConfig,
  ) {
    this.oauthProvider = new MCPOAuthProvider();
  }

  /**
   * Resolve a valid access token for the MCP transport.
   *
   * @returns The access token (and remaining lifetime, when known), or
   *   `undefined` if no valid credentials are available.
   */
  async tokens(): Promise<DynamicOAuthTokens | undefined> {
    // Return the cached token if it is still valid. We only cache tokens whose
    // expiration time is known, so a cached entry always has `expiresAt`.
    if (this.cachedToken && this.cachedToken.expiresAt > Date.now()) {
      return {
        access_token: this.cachedToken.access_token,
        expires_in: this.secondsUntil(this.cachedToken.expiresAt),
      };
    }

    const metadata = await this.oauthProvider.getValidTokenWithMetadata(
      this.serverName,
      this.serverConfig.oauth ?? {},
    );

    if (!metadata) {
      debugLogger.debug(
        `No valid OAuth token available for server: ${this.serverName}`,
      );
      // Drop any stale cache entry so a later successful fetch is not shadowed.
      this.cachedToken = undefined;
      return undefined;
    }

    if (metadata.expiresAt) {
      // Cache tokens with a known expiration to avoid redundant lookups.
      this.cachedToken = {
        access_token: metadata.accessToken,
        expiresAt: metadata.expiresAt,
      };
      return {
        access_token: metadata.accessToken,
        expires_in: this.secondsUntil(metadata.expiresAt),
      };
    }

    // Tokens without an expiration timestamp cannot be cached; they must be
    // re-fetched on every request.
    this.cachedToken = undefined;
    return {
      access_token: metadata.accessToken,
    };
  }

  /**
   * Compute the number of whole seconds until the given absolute timestamp,
   * never returning a negative value.
   */
  private secondsUntil(expiresAt: number): number {
    return Math.max(0, Math.floor((expiresAt - Date.now()) / 1000));
  }
}
